pub fn eval_rpn(expr: Str) -> Result[Int, Str] {
  let tokens = expr.split(" ").filter(fn(t: Str) => not t.is_empty())
  var stack: List[Int] = []
  for tok in tokens {
    if tok == "+" or tok == "-" or tok == "*" or tok == "/" {
      let n = stack.len()
      if n < 2 {
        return Err("stack underflow")
      }
      let b = stack.get_or(n - 1, 0)
      let a = stack.get_or(n - 2, 0)
      var r = 0
      if tok == "+" {
        r = a + b
      } else if tok == "-" {
        r = a - b
      } else if tok == "*" {
        r = a * b
      } else {
        if b == 0 {
          return Err("division by zero")
        }
        r = a / b
      }
      stack = stack.slice(0, n - 2).push(r)
    } else {
      match tok.to_int() {
        Some(v) => { stack = stack.push(v) },
        None => { return Err("bad token {tok}") },
      }
    }
  }
  if stack.len() != 1 {
    return Err("bad expression")
  }
  return Ok(stack.get_or(0, 0))
}
